mapper.select:
SELECT * FROM ( SELECT d.id AS destination_id, d.region_id AS region_id, dt.name, ( SELECT di.image_url FROM destination_images di WHERE di.destination_id = d.id AND di.is_main = 1 ORDER BY di.order_index ASC, di.id ASC LIMIT 1 ) AS image_url, cc.region_name, d.views, ( SELECT COUNT(*) FROM bookmarks b WHERE b.target_type = 'DESTINATION' AND b.target_id = d.id ) AS bookmark_count, MIN(dc.category_id) AS category_id FROM destinations d LEFT JOIN destination_translations dt ON d.id = dt.destination_id AND dt.language_code = 'ko' LEFT JOIN country_categories cc ON d.region_id = cc.id LEFT JOIN destination_categories dc ON d.id = dc.destination_id WHERE dc.category_id IN
#{id}
GROUP BY d.id, d.region_id, dt.name, cc.region_name, d.views ORDER BY (d.views + ( SELECT COUNT(*) FROM bookmarks b WHERE b.target_type = 'DESTINATION' AND b.target_id = d.id )) DESC LIMIT 50 ) t ORDER BY RAND() LIMIT #{limit}
